export const dockerComposeYaml = "services:\n  postgres:\n    image: postgres:16.13-alpine3.23\n    container_name: qorstack-postgres\n    restart: unless-stopped\n    environment:\n      - POSTGRES_DB=qorstack_report\n      - POSTGRES_USER=postgres\n      - POSTGRES_PASSWORD=${DB_PASSWORD}\n    # Not published to the host — only the app talks to it, inside the Docker network\n    # (so nothing clashes with a PostgreSQL already running on this machine).\n    # Need it from a desktop DB client? Uncomment (localhost only; pick another host port if 5432 is taken):\n    # ports:\n    #   - \"127.0.0.1:${DB_HOST_PORT:-5432}:5432\"\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    networks:\n      - qorstack-network\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U postgres\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n\n  # ── S3 storage: RustFS (Apache-2.0) starts by default ─────────────────────\n  # Want MinIO or an external S3 instead? Add ONE override file (see the comments in .env.example):\n  #   COMPOSE_FILE=docker-compose.yml:docker-compose.minio.yml        bundled MinIO (keeps v1 data)\n  #   COMPOSE_FILE=docker-compose.yml:docker-compose.external-s3.yml  AWS S3 / R2 / your own server\n  # The bundled server answers on the network alias \"qorstack-storage\", so STORAGE_ENDPOINT stays the same.\n  # Storage is NOT published to the host: downloads go through the API (/files/...).\n  rustfs:\n    image: rustfs/rustfs:1.0.0\n    container_name: qorstack-rustfs\n    restart: unless-stopped\n    environment:\n      - RUSTFS_ACCESS_KEY=${STORAGE_ACCESS_KEY:-${MINIO_ACCESS_KEY:-qorstack}}\n      - RUSTFS_SECRET_KEY=${STORAGE_SECRET_KEY:-${MINIO_SECRET_KEY:-}}\n      - RUSTFS_VOLUMES=/data\n      - RUSTFS_ADDRESS=0.0.0.0:9000\n      - RUSTFS_CONSOLE_ENABLE=true\n      - RUSTFS_CONSOLE_ADDRESS=0.0.0.0:9001\n    # Uncomment to open the RustFS web console on http://localhost:9001\n    # ports:\n    #   - \"9001:9001\"\n    volumes:\n      - rustfs_data:/data\n    networks:\n      qorstack-network:\n        aliases: [qorstack-storage]\n    healthcheck:\n      # The image ships curl; /health is RustFS's S3-port health endpoint.\n      test: [\"CMD\", \"curl\", \"-fsS\", \"http://localhost:9000/health\"]\n      interval: 10s\n      timeout: 5s\n      retries: 6\n\n  # Mirrors uploaded fonts (STORAGE_BUCKET/fonts/) into the volume Gotenberg reads, every 30 s.\n  # rclone speaks plain S3, so it works with RustFS, MinIO and any external S3.\n  font-syncer:\n    image: rclone/rclone:1.74\n    container_name: qorstack-font-syncer\n    restart: unless-stopped\n    entrypoint: [\"/bin/sh\", \"-c\"]\n    command:\n      - |\n        case \"$$STORAGE_ENDPOINT\" in http://*|https://*) EP=\"$$STORAGE_ENDPOINT\" ;;\n          *) if [ \"$$STORAGE_USE_SSL\" = \"true\" ]; then EP=\"https://$$STORAGE_ENDPOINT\"; else EP=\"http://$$STORAGE_ENDPOINT\"; fi ;; esac\n        export RCLONE_CONFIG_STORE_ENDPOINT=\"$$EP\"\n        echo '[font-syncer] syncing $$STORAGE_BUCKET/fonts every 30s'\n        while true; do\n          rclone sync \"store:$$STORAGE_BUCKET/fonts\" /fonts-cache \\\n            --include \"*.{ttf,otf,woff,woff2,TTF,OTF,WOFF,WOFF2}\" --s3-no-check-bucket -q \\\n            || echo '[font-syncer] storage not reachable yet, retrying'\n          sleep 30\n        done\n    environment:\n      - STORAGE_BUCKET=${STORAGE_BUCKET:-${MINIO_BUCKET:-qorstack-report}}\n      - RCLONE_CONFIG_STORE_TYPE=s3\n      - RCLONE_CONFIG_STORE_PROVIDER=Other\n      - STORAGE_ENDPOINT=${STORAGE_ENDPOINT:-${MINIO_ENDPOINT:-qorstack-storage:9000}}\n      - STORAGE_USE_SSL=${STORAGE_USE_SSL:-${MINIO_USE_SSL:-false}}\n      - RCLONE_CONFIG_STORE_ACCESS_KEY_ID=${STORAGE_ACCESS_KEY:-${MINIO_ACCESS_KEY:-qorstack}}\n      - RCLONE_CONFIG_STORE_SECRET_ACCESS_KEY=${STORAGE_SECRET_KEY:-${MINIO_SECRET_KEY:-}}\n      - RCLONE_CONFIG_STORE_REGION=${STORAGE_REGION:-us-east-1}\n      - RCLONE_CONFIG_STORE_FORCE_PATH_STYLE=true\n    volumes:\n      - fonts_cache:/fonts-cache\n    networks:\n      - qorstack-network\n\n  gotenberg:\n    image: qorstack/gotenberg:8\n    container_name: qorstack-gotenberg\n    restart: unless-stopped\n    command:\n      - \"gotenberg\"\n      - \"--api-port=3000\"\n      - \"--log-level=warn\"\n      - \"--libreoffice-auto-start=true\"\n      - \"--libreoffice-restart-after=100\"\n      - \"--api-disable-health-check-logging=true\"\n    volumes:\n      - fonts_cache:/usr/local/share/fonts/custom\n    networks:\n      - qorstack-network\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:3000/health\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n\n  # Web UI + API in ONE container on ONE port: open http://localhost:8080 — the API is http://localhost:8080/api\n  app:\n    image: qorstack/report:${REPORT_TAG:-latest}\n    container_name: qorstack-report\n    restart: unless-stopped\n    ports:\n      - \"${APP_PORT:-8080}:8080\"\n    environment:\n      - ASPNETCORE_ENVIRONMENT=Production\n      - Admin__Email=${ADMIN_EMAIL}\n      - Admin__Password=${ADMIN_PASSWORD}\n      - ConnectionStrings__DefaultConnection=Host=${DB_HOST:-qorstack-postgres};Port=${DB_PORT:-5432};Database=${DB_NAME:-qorstack_report};Username=${DB_USER:-postgres};Password=${DB_PASSWORD}\n      - Database__MigrationPaths__0=database\n      # S3 storage — STORAGE_* (v1 MINIO_* names still work as fallbacks)\n      - Storage__Endpoint=${STORAGE_ENDPOINT:-${MINIO_ENDPOINT:-qorstack-storage:9000}}\n      - Storage__AccessKey=${STORAGE_ACCESS_KEY:-${MINIO_ACCESS_KEY:-qorstack}}\n      - Storage__SecretKey=${STORAGE_SECRET_KEY:-${MINIO_SECRET_KEY:-}}\n      - Storage__UseSsl=${STORAGE_USE_SSL:-${MINIO_USE_SSL:-false}}\n      - Storage__Region=${STORAGE_REGION:-us-east-1}\n      - Storage__Bucket=${STORAGE_BUCKET:-${MINIO_BUCKET:-qorstack-report}}\n      - Storage__PublicEndpoint=${STORAGE_PUBLIC_ENDPOINT:-${MINIO_PUBLIC_ENDPOINT:-}}\n      # URL people open (web UI + API). Download links are {PUBLIC_URL}/api/files/...\n      - App__PublicUrl=${PUBLIC_URL:-http://localhost:8080}\n      - ImageFetch__AllowPrivateNetworks=${IMAGE_FETCH_ALLOW_PRIVATE_NETWORKS:-false}\n      - Render__AsyncWorkers=${RENDER_ASYNC_WORKERS:-2}\n      - Render__JobLeaseSeconds=${RENDER_JOB_LEASE_SECONDS:-300}\n      - Render__PollSeconds=${RENDER_POLL_SECONDS:-5}\n      - Render__MaxPendingJobsPerUser=${RENDER_MAX_PENDING_JOBS_PER_USER:-100}\n      - Render__MaxBodyMb=${RENDER_MAX_BODY_MB:-30}\n      - Render__MaxTableRows=${RENDER_MAX_TABLE_ROWS:-50000}\n      - Render__MaxItemsPerField=${RENDER_MAX_ITEMS_PER_FIELD:-1000}\n      - Transfer__MaxZipMb=${PROJECT_IMPORT_MAX_MB:-200}\n      - Webhook__SigningSecret=${WEBHOOK_SIGNING_SECRET:-}\n      - Webhook__AllowPrivateNetworks=${WEBHOOK_ALLOW_PRIVATE_NETWORKS:-false}\n      - Gotenberg__BaseUrl=http://qorstack-gotenberg:3000\n      - Fonts__RendererCachePath=/renderer-fonts   # read-only view of the font-syncer volume → GET /fonts/status\n      - Jwt__Key=${JWT_KEY}\n      - Jwt__Issuer=qorstack-report\n      - Jwt__Audience=qorstack-report\n      - Encryption__Key=${ENCRYPTION_KEY}\n      - Encryption__IV=${ENCRYPTION_IV}\n      # Only for browser apps on OTHER origins that call the API directly (the built-in UI needs nothing).\n      - Cors__AllowedOriginsString=${CORS_ORIGINS:-}\n      - Auth__CookieSecure=${AUTH_COOKIE_SECURE:-}\n      # Optional social sign-in (leave empty to use username/password only)\n      - Google__ClientId=${GOOGLE_CLIENT_ID:-}\n      - GitHub__ClientId=${GITHUB_CLIENT_ID:-}\n      - GitHub__ClientSecret=${GITHUB_CLIENT_SECRET:-}\n      # --- Pro license (optional) ---\n      # Have a Pro license? You received a file named like:  license-you_at_example_com.json\n      # 1) Put that file next to this docker-compose.yml (keep its original name).\n      # 2) Uncomment the line below AND the license line under `volumes:` further down (put your\n      #    file name on its left), then run: docker compose up -d   (`restart` does not apply changes)\n      #    left  = your downloaded file   |   right = /app/license.json (fixed path the backend reads — don't change)\n      # - Pro__LicenseFile=/app/license.json\n    depends_on:\n      postgres:\n        condition: service_healthy\n      rustfs:\n        condition: service_healthy\n        required: false   # disabled by the minio / external-s3 override files\n    volumes:\n      - fonts_cache:/renderer-fonts:ro\n      # Pro license (see step 2 above):\n      # - ./license-you_at_example_com.json:/app/license.json:ro\n    networks:\n      - qorstack-network\n\nvolumes:\n  postgres_data:\n  rustfs_data:\n  fonts_cache:\n\nnetworks:\n  qorstack-network:\n    driver: bridge\n"

export const envExample = "# =============================================================================\n# Qorstack Report — self-host configuration\n#\n# Quick start:\n#   bash init.sh            # copies this file to .env and fills every change-me-* with random secrets\n#   docker compose up -d    # then open http://localhost:8080 (web UI; the API is under /api)\n#\n# Every value below works as-is on one machine (localhost). Only the lines marked\n# \"PRODUCTION\" need changing when you put the stack behind a real domain.\n# =============================================================================\n\n\n# ── Admin account ────────────────────────────────────────────────────────────\n# The system admin is re-synced from these values on EVERY backend start.\n# To rotate the password: change it here, then `docker compose up -d` again.\n# ADMIN_EMAIL may be a plain username (e.g. \"admin\") or an e-mail address.\nADMIN_EMAIL=admin\nADMIN_PASSWORD=admin\n\n\n# ── PostgreSQL ───────────────────────────────────────────────────────────────\n# Defaults point at the bundled `postgres` container. To use an external database,\n# set DB_HOST/DB_PORT to it and remove the postgres service from docker-compose.yml.\nDB_HOST=qorstack-postgres\nDB_PORT=5432\nDB_NAME=qorstack_report\nDB_USER=postgres\n# Password for the bundled container AND the backend connection (generated by init.sh).\nDB_PASSWORD=change-me-db-password\n\n\n# ── File storage (S3) ────────────────────────────────────────────────────────\n# Storage server: RustFS (Apache-2.0) is bundled and starts by default — nothing to set.\n# To use something else, uncomment ONE line (Docker Compose reads COMPOSE_FILE from this file):\n#   bundled MinIO instead of RustFS (v1 installs that keep their MinIO data):\n# COMPOSE_FILE=docker-compose.yml:docker-compose.minio.yml\n#   no bundled server — external S3 (AWS S3, Cloudflare R2, your own MinIO/RustFS); set STORAGE_* below:\n# COMPOSE_FILE=docker-compose.yml:docker-compose.external-s3.yml\n# Keeps \":\" as the COMPOSE_FILE separator on every OS (Windows defaults to \";\").\nCOMPOSE_PATH_SEPARATOR=:\n# Address the backend + font-syncer use INSIDE the Docker network (host:port, no scheme).\n# \"qorstack-storage\" is the network alias of the bundled server (RustFS or MinIO).\nSTORAGE_ENDPOINT=qorstack-storage:9000\n# true only when STORAGE_ENDPOINT speaks HTTPS (e.g. AWS S3: s3.eu-central-1.amazonaws.com).\nSTORAGE_USE_SSL=false\n# Region — most self-hosted servers accept the default. AWS S3: your bucket's region.\nSTORAGE_REGION=us-east-1\n# Credentials. For the bundled server these BECOME its root user/password (first start only).\n# The access key must not contain \"/\". STORAGE_SECRET_KEY is generated by init.sh.\nSTORAGE_ACCESS_KEY=qorstack\nSTORAGE_SECRET_KEY=change-me-storage-secret\n# The ONE bucket that holds everything. Created automatically on start, with folders:\n#   template/          uploaded Word / Excel templates\n#   generated-report/  generated files, sandbox assets, temporary downloads (deleted after 1 day)\n#   fonts/             fonts uploaded from the Fonts page (mirrored to Gotenberg by font-syncer)\nSTORAGE_BUCKET=qorstack-report\n# Storage does NOT need a public address: every download link points at the API\n# ({PUBLIC_URL}/api/files/...), which streams the file. Port 9000 is not published.\n# Already serve storage on its own public address (e.g. https://storage.example.com)? Set it here and\n# download links become presigned URLs for that address (browsers fetch from storage directly, as in v1).\n# STORAGE_PUBLIC_ENDPOINT=\n#\n# Upgrading from v1? Your old .env has MINIO_* names — they still work (STORAGE_* wins when\n# both are set). Before starting v2, copy the old data once: `bash migrate-storage.sh`\n# (see README › Upgrading to v2).\n\n\n# ── Image URLs in render requests ────────────────────────────────────────────\n# Image / QR-logo URLs are downloaded by the backend. For safety it refuses private and\n# internal addresses (localhost, 10.x, 172.16–31.x, 192.168.x, 100.64–127.x, cloud metadata).\n# Set true ONLY if your images live on an intranet server and every API-key holder is trusted.\nIMAGE_FETCH_ALLOW_PRIVATE_NETWORKS=false\n\n# ── Render request limits ────────────────────────────────────────────────────\n# Protect the server from oversized render requests. 0 = unlimited.\n# A request over a limit gets 400 naming the field and the setting to raise.\n# Max request body in MB (keep it below your reverse proxy limit, e.g. nginx client_max_body_size).\nRENDER_MAX_BODY_MB=30\n# Max rows in one table.\nRENDER_MAX_TABLE_ROWS=50000\n# Max items in each of replace / image / qrcode / barcode.\nRENDER_MAX_ITEMS_PER_FIELD=1000\n\n# ── Project export / import (Pro) ────────────────────────────────────────────\n# Largest project ZIP accepted by Export & import → Import (MB). Keep it below your reverse proxy limit.\nPROJECT_IMPORT_MAX_MB=200\n\n\n# ── Async renders + webhooks (Pro) ───────────────────────────────────────────\n# \"async\": true queues a render and returns 202 with a job id; poll GET /render/jobs/{id}.\n# Jobs are stored in PostgreSQL (report_jobs): they survive restarts, and several backend\n# replicas can share the queue. A job whose worker dies is picked up again when its lease ends;\n# network/storage/Gotenberg errors are retried (after 10 s, then 60 s, 3 tries in total).\n# Parallel async renders per backend (each uses CPU + one Gotenberg conversion).\nRENDER_ASYNC_WORKERS=2\n# How long a worker may hold a job before another worker can take it over (renewed while rendering).\nRENDER_JOB_LEASE_SECONDS=300\n# Workers are woken instantly (LISTEN/NOTIFY); this poll is the fallback.\nRENDER_POLL_SECONDS=5\n# Unfinished async renders allowed per user; more → 429 Too Many Requests.\nRENDER_MAX_PENDING_JOBS_PER_USER=100\n# Webhooks are tried 3 times (now, +10 s, +60 s); delivery state is stored, so restarts only delay them.\n# Secret for the X-Qorstack-Signature header on webhook POSTs (sha256=HMAC of the body).\n# Generated by init.sh; empty = unsigned webhooks.  Generate: openssl rand -hex 32\nWEBHOOK_SIGNING_SECRET=change-me-webhook-signing-secret\n# Webhooks to private / internal addresses are refused unless this is true (same rule as image URLs).\nWEBHOOK_ALLOW_PRIVATE_NETWORKS=false\n\n# ── Security keys (generated by init.sh — never reuse the examples) ──────────\n# JWT signing key, at least 32 characters.  Generate: openssl rand -hex 24\nJWT_KEY=change-me-jwt-signing-key-at-least-32-chars\n# AES key for stored secrets, EXACTLY 32 characters.  Generate: openssl rand -hex 16\n# Do not change after first start — data encrypted with the old key can no longer be read.\nENCRYPTION_KEY=change-me-encryption-key-32char!\n# AES IV, EXACTLY 16 characters.  Generate: openssl rand -hex 8\nENCRYPTION_IV=change-me-iv-16!\n\n\n# ── Web app + API (one container, one port) ──────────────────────────────────\n# Host port. Open http://localhost:8080 for the web UI; the API is http://localhost:8080/api\nAPP_PORT=8080\n# The address people open (put in download links: {PUBLIC_URL}/api/files/...).\n# PRODUCTION: e.g. https://report.example.com\nPUBLIC_URL=http://localhost:8080\n# Only needed for browser apps on OTHER origins that call the API directly. Comma-separated.\n# The built-in web UI is on the same origin and needs nothing here.\nCORS_ORIGINS=\n# Sign-in cookies follow the address in the browser: Secure on https://, plain on http:// (a NodePort,\n# an intranet IP), so both work with no setting. Set true/false only to force one.\n# AUTH_COOKIE_SECURE=\n\n# ── Social sign-in (optional) ────────────────────────────────────────────────\n# Leave empty to sign in with username/password only.\n# Google: OAuth client id (Google Cloud Console → Credentials), authorised origin = PUBLIC_URL.\nGOOGLE_CLIENT_ID=\n# GitHub: OAuth app (github.com/settings/developers), callback = {PUBLIC_URL}/auth/github/callback\nGITHUB_CLIENT_ID=\nGITHUB_CLIENT_SECRET=\n\n\n# ── Image versions ───────────────────────────────────────────────────────────\n# Leave unset to track :latest, or pin a release for reproducible deploys.\n# REPORT_TAG=2.2.2\n"
